// Words that pull 2D styles toward photorealism. Softened only when a 2D style is active.
const BB_REALISM_SWAPS = [
  [/\bphoto ?realistic\b/gi, 'illustrated'],
  [/\bhyper ?realistic\b/gi, 'illustrated'],
  [/\b(gleaming|glossy|shiny) /gi, 'bright '],
  [/\breflections?\b/gi, 'simple highlights'],
  [/\b(8k|4k|ultra detailed|hdr)\b/gi, ''],
  [/\bbokeh\b/gi, 'soft background'],
  [/\bcinematic lighting\b/gi, 'clear lighting'],
  [/\bvolumetric (light|lighting|fog)\b/gi, 'soft light']
];
